const WEEKDAYS = ['Thursday', 'Friday', 'Saturday', 'Sunday', 'Monday', 'Tuesday', 'Wednesday']; // 1 Oct 2026 is a Thursday
const longDate = (d: number) => `${WEEKDAYS[(d - 1) % 7]} ${d} October 2026`;
const shortDate = (d: number) => `${WEEKDAYS[(d - 1) % 7].slice(0, 3)} ${d} Oct 2026`;
const arrival = (t: string) => {
  const m = t.match(/(\d+):(\d+) (AM|PM)/);
  if (!m) return t;
  let mins = ((+m[1] % 12) + (m[3] === 'PM' ? 12 : 0)) * 60 + +m[2] - 15;
  if (mins < 0) mins += 1440;
  let hh = Math.floor(mins / 60);
  const ap = hh >= 12 ? 'PM' : 'AM';
  hh = hh % 12 || 12;
  return `${String(hh).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')} ${ap}`;
};

